class PackedOwnedEvidenceReplacementTest {
	private static final int ROWS = 8192;
	private static final PackedStatementPatternSemanticsCodec CODEC = LmdbOwnedCacheCodecTestSupport.codec();
	private static final PackedPlanCache.Context CONTEXT = new PackedPlanCache.Context(1, 2, 3, 4, 5, 6, 7);
	private static final PackedCostModel MODEL = new ExactTableCostModel();

	@Test
	void actualOwnedEvidenceVictimCanBeStrippedHitEvictedAndRetainedAgain() {
		assertTrue(CODEC.ownsCacheValues(), "use the actual production LMDB cache-only ownership adapter");
		TupleExpr first = source("urn:evidence:first");
		TupleExpr second = new Projection(source("urn:evidence:other"),
				new ProjectionElemList(new ProjectionElem("object")));
		long budget = PackedCacheCapacityTestSupport.evidenceCapacity(first, second, CONTEXT, MODEL, CODEC);
		PackedPlanCache cache = new PackedPlanCache(8, 1, budget);

		String oversizedPredicate = "urn:evidence:" + "x".repeat(Math.toIntExact(budget));
		TupleExpr largeFamilyInvocation = source(oversizedPredicate);
		TupleExpr oversized = new Extension(source(oversizedPredicate),
				new ExtensionElem(Var.of("object"), "evidenceAlias"));
		PackedQueryCacheIdentity firstIdentity = PackedQueryCacheIdentity.createPlanIdentity(first, null, CODEC);
		PackedQueryCacheIdentity secondIdentity = PackedQueryCacheIdentity.createPlanIdentity(second, null, CODEC);
		PackedQueryCacheIdentity largeIdentity = PackedQueryCacheIdentity.createPlanIdentity(largeFamilyInvocation,
				null,
				CODEC);
		PackedQueryCacheIdentity oversizedIdentity = PackedQueryCacheIdentity.createPlanIdentity(oversized, null,
				CODEC);
		assertNotNull(firstIdentity, "the retained first query has a complete cache identity");
		assertNotNull(secondIdentity, "the retained projected query has a complete cache identity");
		assertNotNull(largeIdentity, "the large predicate invocation has a complete cache identity");
		assertNotNull(oversizedIdentity, "the supported extension query has a complete cache identity");
		assertFalse(firstIdentity.matches(largeIdentity), "the large predicate is a different exact invocation");
		PackedQueryFamilyIdentity firstFamily = PackedQueryFamilyIdentity.create(first, null, CODEC);
		PackedQueryFamilyIdentity secondFamily = PackedQueryFamilyIdentity.create(second, null, CODEC);
		PackedQueryFamilyIdentity largeFamily = PackedQueryFamilyIdentity.create(largeFamilyInvocation, null, CODEC);
		PackedQueryFamilyIdentity oversizedFamily = PackedQueryFamilyIdentity.create(oversized, null, CODEC);
		assertNotNull(firstFamily, "the retained first query has a complete parameterized family");
		assertNotNull(secondFamily, "the retained projected query has a complete parameterized family");
		assertNotNull(largeFamily, "the large predicate invocation has a complete parameterized family");
		assertNotNull(oversizedFamily, "the extension query has a complete parameterized family");
		assertTrue(firstFamily.matches(largeFamily), "the large predicate varies within the first query family");
		assertTrue(PackedQueryFamilyIdentity.sameConcreteInvocation(firstFamily, largeFamily),
				"the large predicate invocation must take the existing family-materialization path");
		assertFalse(largeFamily.matches(secondFamily), "the large predicate is not the projected second family");
		assertFalse(oversizedFamily.matches(firstFamily),
				"the extension is a distinct third family from the first retained query");
		assertFalse(oversizedFamily.matches(secondFamily),
				"the extension is a distinct third family from the projected retained query");
		assertFalse(oversizedIdentity.matches(firstIdentity), "the extension cannot exact-hit the first query");
		assertFalse(oversizedIdentity.matches(secondIdentity), "the extension cannot exact-hit the projected query");
		StatementPattern largeSourcePattern = assertInstanceOf(StatementPattern.class, largeFamilyInvocation);
		StatementPattern oversizedSourcePattern = assertInstanceOf(StatementPattern.class,
				assertInstanceOf(Extension.class, oversized).getArg());
		assertEquals(largeSourcePattern.getPredicateVar().getValue(),
				oversizedSourcePattern.getPredicateVar().getValue(),
				"the family hit and third-family refusal use the same oversized predicate value");

		for (int cycle = 0; cycle < 3; cycle++) {
			assertFalse(plan(cache, first).metrics().planCacheHit(), "the preceding refusal must evict all owners");
			assertTrue(plan(cache, first).metrics().planCacheHit(), "a small real query must retain a genuine plan");
			PackedPlanCache.PlanEntry original = entry(cache, first);
			assertNotNull(original);
			assertTrue(original.recipe().hasDetachedEvidence());
			PackedPlanningResult incoming = plan(cache, second);
			assertFalse(incoming.metrics().planCacheHit());
			assertEquals(ROWS, incoming.outputRows(), "the projected exact-table source keeps every row");
			assertEquals(Set.of("object"), incoming.selectedPlan().getBindingNames());
			PackedPlanCache.PlanEntry stripped = entry(cache, first);
			assertNotNull(stripped, "evidence pressure must replace the existing victim, not select a capacity victim");
			assertNotSame(original, stripped, "this must exercise the new entry/private-source ownership transition");
			assertFalse(stripped.recipe().hasDetachedEvidence());
			assertTrue(entry(cache, second).recipe().hasDetachedEvidence(), "the new complete evidence won admission");
			assertTrue(plan(cache, first).metrics().planCacheHit(), "the stripped physical recipe remains reusable");
			assertTrue(plan(cache, second).metrics().planCacheHit());

			PackedPlanCache.PlanEntry firstBeforeFamilyHit = entry(cache, first);
			PackedPlanCache.PlanEntry secondBeforeFamilyHit = entry(cache, second);
			assertNotNull(firstBeforeFamilyHit);
			assertNotNull(secondBeforeFamilyHit);
			PackedPlanCache.Fingerprint largeFingerprint = cache.fingerprint(largeFamilyInvocation, largeIdentity);
			PackedPlanCache.OwnershipSnapshot beforeFamilyHit = cache.ownershipSnapshot(largeFingerprint, CONTEXT);
			assertEquals(PackedPlanCache.OwnershipCoverage.COMPLETE_OWNED, beforeFamilyHit.coverage());
			assertEquals(4, beforeFamilyHit.roots().size(), "both retained Plan/Query pairs must be covered");
			assertTrue(beforeFamilyHit.roots().stream().anyMatch(root -> root.planEntry() == firstBeforeFamilyHit));
			assertTrue(beforeFamilyHit.roots().stream().anyMatch(root -> root.planEntry() == secondBeforeFamilyHit));
			assertFalse(beforeFamilyHit.roots()
					.stream()
					.anyMatch(root -> root.kind() == PackedPlanCache.OwnershipKind.FLIGHT),
					"the synchronous retained state has no active flight");
			PackedPlanningResult rebound = plan(cache, largeFamilyInvocation);
			assertTrue(rebound.metrics().planCacheHit(), "the large invocation must be a warm family hit");
			assertFalse(rebound.metrics().queryTemplateCacheHit(),
					"the large invocation must materialize the current family query, not an exact template hit");
			assertEquals(ROWS, rebound.outputRows(), "family materialization must keep every source row");
			StatementPattern emitted = assertInstanceOf(StatementPattern.class, rebound.selectedPlan());
			assertEquals(oversizedPredicate, emitted.getPredicateVar().getValue().stringValue(),
					"the emitted plan must contain this invocation's large predicate");
			PackedPlanCache.OwnershipSnapshot afterFamilyHit = cache.ownershipSnapshot(largeFingerprint, CONTEXT);
			assertSameOwnershipSnapshot(beforeFamilyHit, afterFamilyHit);

			// This supported third family carries the same large predicate but cannot hit either retained family. Its
			// mandatory owned source cannot fit the existing identity budget, so the ordinary uncached path must
			// release
			// every owner. The original miss, row-count, eviction and three-cycle re-retention oracles remain below.
			PackedPlanningResult uncached = assertDoesNotThrow(() -> plan(cache, oversized));
			assertFalse(uncached.metrics().planCacheHit());
			assertEquals(ROWS, uncached.outputRows());
			assertNull(entry(cache, first));
			assertNull(entry(cache, second));
		}
		assertFalse(plan(cache, first).metrics().planCacheHit());
		assertTrue(plan(cache, first).metrics().planCacheHit(),
				"all replacement owners must release under the same budget");
	}

	@Test
	void ownedEvidenceCopyViewUsesTheExistingProducerWithoutMutatingReservations() {
		TupleExpr source = source("urn:evidence:copy-view");
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		assertFalse(plan(cache, source).metrics().planCacheHit());
		PackedPlanCache.PlanEntry original = entry(cache, source);
		assertNotNull(original);
		PackedPlanCache.OwnershipSnapshot before = cache.ownershipSnapshot(cache.fingerprint(source), CONTEXT);
		PackedPlanCache.OwnershipRoot root = before.roots()
				.stream()
				.filter(candidate -> candidate.planEntry() == original)
				.findFirst()
				.orElseThrow();
		assertTrue(original.recipe().hasDetachedEvidence());
		PackedPlanCache.OwnershipRoot copy = root.withoutDetachedEvidence();
		assertNotSame(root.identity(), copy.identity());
		assertNotSame(original, copy.planEntry());
		assertFalse(copy.planEntry().recipe().hasDetachedEvidence());
		assertEquals(original.outputRows(), copy.planEntry().outputRows());
		assertEquals(original.totalCost(), copy.planEntry().totalCost());
		assertEquals(original.completionStatus(), copy.planEntry().completionStatus());
		assertSame(original, entry(cache, source));
		assertTrue(original.recipe().hasDetachedEvidence());
		PackedPlanCache.OwnershipSnapshot after = cache.ownershipSnapshot(cache.fingerprint(source), CONTEXT);
		assertEquals(before.identityBytes(), after.identityBytes());
		assertEquals(before.separatelyReservedBytes(), after.separatelyReservedBytes());
		for (int index = 0; index < before.roots().size(); index++) {
			assertSame(before.roots().get(index).identity(), after.roots().get(index).identity());
		}
		PackedProviderIdentityBudget ledger = new PackedProviderIdentityBudget(Long.MAX_VALUE);
		assertTrue(ledger.tryRetain(copy.identity()));
		assertTrue(ledger.bytes() > 0L);
		ledger.release(copy.identity());
		assertEquals(0L, ledger.bytes());
	}

	private static TupleExpr source(String predicate) {
		return new StatementPattern(Var.of("subject"),
				Var.of("predicate", SimpleValueFactory.getInstance().createIRI(predicate)), Var.of("object"));
	}

	private static PackedPlanningResult plan(PackedPlanCache cache, TupleExpr source) {
		return PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache, CONTEXT, MODEL, null, CODEC);
	}

	private static PackedPlanCache.PlanEntry entry(PackedPlanCache cache, TupleExpr source) {
		PackedQueryCacheIdentity identity = PackedQueryCacheIdentity.createPlanIdentity(source, null, CODEC);
		assertNotNull(identity, "the actual ready source must have a complete collision-proof identity");
		return cache.findPlan(cache.fingerprint(source, identity), CONTEXT, source, identity,
				PackedPlannerLimits.unbounded());
	}

	private static void assertSameOwnershipSnapshot(PackedPlanCache.OwnershipSnapshot expected,
			PackedPlanCache.OwnershipSnapshot actual) {
		assertEquals(expected.coverage(), actual.coverage());
		assertEquals(expected.identityBytes(), actual.identityBytes(), "owned identity bytes must be unchanged");
		assertEquals(expected.separatelyReservedBytes(), actual.separatelyReservedBytes(),
				"separately reserved evidence bytes must be unchanged");
		assertEquals(expected.capacityBytes(), actual.capacityBytes());
		assertEquals(expected.roots().size(), actual.roots().size(), "owned cache root count must be unchanged");
		for (int index = 0; index < expected.roots().size(); index++) {
			PackedPlanCache.OwnershipRoot before = expected.roots().get(index);
			PackedPlanCache.OwnershipRoot after = actual.roots().get(index);
			assertEquals(before.kind(), after.kind(), "root kind at index " + index);
			assertSame(before.identity(), after.identity(), "root identity at index " + index);
			assertSame(before.planEntry(), after.planEntry(), "PlanEntry at index " + index);
		}
	}

	/**
	 * Genuine public cost-session/payload protocol over an immutable one-column test table, not native/source
	 * authority.
	 */
	private static final class ExactTableCostModel implements PackedCostModel {
		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return ROWS;
		}

		@Override
		public PackedCostSession openSession(PackedQueryView query) {
			return new PackedCostSession() {
				private final FrontierStateArena arena = new FrontierStateArena(2L * 1024L * 1024L);
				private final EvidenceStateRef state = prepare();

				private EvidenceStateRef prepare() {
					FrontierStateKey key = FrontierStateKey.of(new long[] { 1L },
							FrontierMaskStrata.of(FrontierLayout.of("object"), 1, new long[] { 1L }),
							0L, 0L, 0L, 0L, 0L, 0L, FrontierLaneFamily.DESIGN, 0, 1);
					arena.declareCanonicalStates(key);
					try (FrontierPayloadWriter writer = arena.newPayloadWriter(key, new int[] { ROWS },
							new int[] { 0 })) {
						long[] tuple = new long[1];
						for (int row = 0; row < ROWS; row++) {
							tuple[0] = row + 1L;
							writer.putExact(0, row, 1.0d, tuple, 0);
						}
						return arena.internPayload(key, EvidenceStateSummary.exact(ROWS),
								FrontierStateOperation.EXACT_LEAF, null, null, 0, writer);
					}
				}

				@Override
				public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
					output.setRows(ROWS, ROWS);
					output.setEvidenceStateId(state.stateId());
					output.setEvidenceGuarantee(state.summary().guarantee());
					output.setEvidenceDisposition(FrontierStateDisposition.COMPOSABLE_PAYLOAD);
				}

				@Override
				public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
					estimateLeaf(relationId, context, output);
				}

				@Override
				public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
					estimateLeaf(relationId, context, output);
				}

				@Override
				public FrontierEvidenceBundle detachEvidence(int[] evidenceStateIds) {
					return arena.exportEvidence(evidenceStateIds);
				}

				@Override
				public void close() {
					arena.close();
				}
			};
		}
	}
}
